mapper.select:
SELECT UC.*, UCI.IMAGE_ID, UCI.IMAGE_URL, UCI.MAIN_IMAGE
FROM USED_CAR UC
LEFT JOIN USED_CAR_IMAGE UCI ON UC.VEHICLE_NO = UCI.VEHICLE_NO
WHERE 1=1

    AND LOWER(UC.VEHICLE_NAME) LIKE LOWER(#{vehicleName}) || '%'


    AND UC.VEHICLE_TYPE = #{vehicleType}


    AND UC.BRAND = #{brand}


    AND UC.MODEL_YEAR = #{modelYear}


    AND UC.PRICE >= #{minPrice}


    AND UC.PRICE <= #{maxPrice}


    AND UC.COLOR = #{color}


    AND UC.DEALER_LOCATION = #{dealerLocation}


     AND LOWER(UC.FUEL_TYPE) = LOWER(#{fuelType})


    AND UC.TRANSMISSION = #{transmission}


    AND UC.DRIVE_TYPE = #{driveType}


    AND UC.CAR_KM >= #{minKm}


    AND UC.CAR_KM <= #{maxKm}


    AND UC.SEATING_CAPACITY = #{seatingCapacity}

ORDER BY 


        UC.CAR_KM


        UC.PRICE


        UC.MODEL_YEAR


        UC.CAR_KM




        ASC


        DESC

,
UCI.IMAGE_ID ASC

mapper.update:
UPDATE USED_CAR_IMAGE
SET MAIN_IMAGE = 'Y'
WHERE VEHICLE_NO = #{vehicleNo} AND IMAGE_URL = #{imageUrl}

UPDATE USED_CAR
SET MAIN_IMAGE = #{mainImage}
WHERE VEHICLE_NO = #{vehicleNo}
